public class Solution {
    public static String[] customSplit(String text, char delimiter) {
        List<String> tokens = new ArrayList<>();
        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < text.length(); i++) {
            char ch = text.charAt(i);
            if (ch == delimiter) {
                tokens.add(sb.toString());
                sb.setLength(0);
            } else {
                sb.append(ch);
            }
        }
        tokens.add(sb.toString());
        return tokens.toArray(new String[0]);
    }

    public static void main(String[] args) {
        String data = "apple:banana:cherry:date";
        String[] parts = customSplit(data, ':');
        System.out.println("Custom split tokens: " + Arrays.toString(parts));
    }
}

public class Solution {
    public static boolean containsIgnoreCase(String source, String target) {
        if (source == null || target == null || target.length() > source.length()) {
            return false;
        }
        int max = source.length() - target.length();
        for (int i = 0; i <= max; i++) {
            if (source.regionMatches(true, i, target, 0, target.length())) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        String text = "Enterprise JAVA Architecture";
        String query = "java";
        System.out.println("Contains '" + query + "' (case-insensitive): " + containsIgnoreCase(text, query));
    }
}

public class Solution {
    public static int countOccurrences(String text, String sub, boolean allowOverlap) {
        if (text == null || sub == null || sub.isEmpty()) return 0;
        int count = 0;
        int idx = 0;
        while ((idx = text.indexOf(sub, idx)) != -1) {
            count++;
            idx += allowOverlap ? 1 : sub.length();
        }
        return count;
    }

    public static void main(String[] args) {
        String data = "banana";
        System.out.println("Non-overlapping 'an' in 'banana': " + countOccurrences(data, "an", false));
        System.out.println("Overlapping 'ana' in 'banana':     " + countOccurrences(data, "ana", true));
    }
}

public class Solution {
    public static String toTitleCase(String input) {
        if (input == null || input.isEmpty()) return input;
        String[] words = input.trim().split("\\s+");
        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < words.length; i++) {
            String w = words[i];
            if (!w.isEmpty()) {
                sb.append(Character.toUpperCase(w.charAt(0)));
                if (w.length() > 1) {
                    sb.append(w.substring(1).toLowerCase());
                }
                if (i < words.length - 1) sb.append(" ");
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        String raw = "jAvA bAcKeNd dEvElOpEr";
        System.out.println("Input:  " + raw);
        System.out.println("Output: " + toTitleCase(raw));
    }
}

public class Solution {
    public static String maskCardNumber(String card) {
        if (card == null || card.length() <= 4) {
            return card;
        }
        int maskLength = card.length() - 4;
        String mask = "*".repeat(maskLength);
        String suffix = card.substring(maskLength);
        return mask + suffix;
    }

    public static void main(String[] args) {
        String creditCard = "4532789012345678";
        String masked = maskCardNumber(creditCard);
        System.out.println("Card:   " + creditCard);
        System.out.println("Masked: " + masked);
    }
}

