import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static void main(String[] args) {
        String sentence = "Java developers write robust Java applications with modern Java";
        String[] words = sentence.toLowerCase().split("\\s+");

        String longest = "";
        Map<String, Integer> counts = new HashMap<>();

        for (String w : words) {
            if (w.length() > longest.length()) {
                longest = w;
            }
            counts.put(w, counts.getOrDefault(w, 0) + 1);
        }

        String mostFrequent = "";
        int maxCount = 0;
        for (Map.Entry<String, Integer> entry : counts.entrySet()) {
            if (entry.getValue() > maxCount) {
                maxCount = entry.getValue();
                mostFrequent = entry.getKey();
            }
        }

        System.out.println("Longest word: " + longest);
        System.out.println("Most frequent word: '" + mostFrequent + "' (" + maxCount + " times)");
    }
}

public class Solution {
    public static boolean validateManual(String email) {
        if (email == null) return false;
        int at = email.indexOf('@');
        int lastAt = email.lastIndexOf('@');
        if (at <= 0 || at != lastAt) return false; // Must contain exactly one '@', not at start
        int dot = email.indexOf('.', at + 1);
        return dot > at + 1 && dot < email.length() - 2; // Domain must have dot with extension
    }

    public static boolean validateRegex(String email) {
        if (email == null) return false;
        return email.matches("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
    }

    public static void main(String[] args) {
        String test = "dev.user@cloud.com";
        System.out.println("Email: " + test);
        System.out.println("Manual validation: " + validateManual(test));
        System.out.println("Regex validation:  " + validateRegex(test));
    }
}

public class Solution {
    public static String compress(String s) {
        if (s == null || s.isEmpty()) return "";
        StringBuilder sb = new StringBuilder();
        int count = 1;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) == s.charAt(i - 1)) {
                count++;
            } else {
                sb.append(s.charAt(i - 1)).append(count);
                count = 1;
            }
        }
        sb.append(s.charAt(s.length() - 1)).append(count);
        return sb.toString();
    }

    public static String decompress(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i += 2) {
            char ch = s.charAt(i);
            int count = Character.getNumericValue(s.charAt(i + 1));
            for (int k = 0; k < count; k++) {
                sb.append(ch);
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        String original = "aaabbc";
        String compressed = compress(original);
        String restored = decompress(compressed);

        System.out.println("Original:     " + original);
        System.out.println("Compressed:   " + compressed);
        System.out.println("Decompressed: " + restored);
    }
}

import java.util.Arrays;

public class Solution {
    public static int search(String text, String pattern) {
        int n = text.length();
        int m = pattern.length();
        if (m == 0) return 0;
        if (m > n) return -1;

        int[] badChar = new int[256];
        Arrays.fill(badChar, m);
        for (int i = 0; i < m - 1; i++) {
            badChar[pattern.charAt(i)] = m - 1 - i;
        }

        int i = 0;
        while (i <= n - m) {
            int j = m - 1;
            while (j >= 0 && pattern.charAt(j) == text.charAt(i + j)) {
                j--;
            }
            if (j < 0) return i; // Match found
            i += badChar[text.charAt(i + m - 1)];
        }
        return -1;
    }

    public static void main(String[] args) {
        String text = "BREAD AND BUTTER";
        String pattern = "BUTTER";
        System.out.println("Pattern offset: " + search(text, pattern));
    }
}

public class Solution {
    public static int computeLevenshtein(String s1, String s2) {
        int m = s1.length(), n = s2.length();
        int[][] dp = new int[m + 1][n + 1];

        for (int i = 0; i <= m; i++) dp[i][0] = i;
        for (int j = 0; j <= n; j++) dp[0][j] = j;

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1];
                } else {
                    dp[i][j] = 1 + Math.min(dp[i - 1][j - 1], // substitution
                                   Math.min(dp[i - 1][j],     // deletion
                                            dp[i][j - 1]));   // insertion
                }
            }
        }
        return dp[m][n];
    }

    public static void main(String[] args) {
        String a = "kitten";
        String b = "sitting";
        System.out.println("Edit distance ('" + a + "' -> '" + b + "'): " + computeLevenshtein(a, b));
    }
}

import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static String interpolate(String template, Map<String, String> values) {
        StringBuilder sb = new StringBuilder();
        int cursor = 0;
        int start;

        while ((start = template.indexOf("${", cursor)) != -1) {
            int end = template.indexOf("}", start + 2);
            if (end == -1) break;
            sb.append(template, cursor, start);
            String key = template.substring(start + 2, end);
            sb.append(values.getOrDefault(key, "${unresolved:" + key + "}"));
            cursor = end + 1;
        }
        sb.append(template.substring(cursor));
        return sb.toString();
    }

    public static void main(String[] args) {
        String template = "Hello ${name}, your order ${orderId} is confirmed.";
        Map<String, String> params = new HashMap<>();
        params.put("name", "Akshat");
        params.put("orderId", "ORD-2026");

        System.out.println(interpolate(template, params));
    }
}

import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static List<String> parseCsvLine(String line) {
        List<String> fields = new ArrayList<>();
        StringBuilder sb = new StringBuilder();
        boolean inQuotes = false;

        for (int i = 0; i < line.length(); i++) {
            char ch = line.charAt(i);
            if (ch == '"') {
                inQuotes = !inQuotes;
            } else if (ch == ',' && !inQuotes) {
                fields.add(sb.toString().trim());
                sb.setLength(0);
            } else {
                sb.append(ch);
            }
        }
        fields.add(sb.toString().trim());
        return fields;
    }

    public static void main(String[] args) {
        String csv = "101, \"Doe, John\", 45, \"Engineer, Senior\"";
        List<String> parsed = parseCsvLine(csv);
        System.out.println("Parsed CSV fields:");
        for (int i = 0; i < parsed.size(); i++) {
            System.out.println((i + 1) + ": " + parsed.get(i));
        }
    }
}

public class Solution {
    public static String computeLCS(String s1, String s2) {
        int m = s1.length(), n = s2.length();
        int[][] dp = new int[m + 1][n + 1];

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
                    dp[i][j] = 1 + dp[i - 1][j - 1];
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        int i = m, j = n;
        while (i > 0 && j > 0) {
            if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
                sb.append(s1.charAt(i - 1));
                i--;
                j--;
            } else if (dp[i - 1][j] > dp[i][j - 1]) {
                i--;
            } else {
                j--;
            }
        }
        return sb.reverse().toString();
    }

    public static void main(String[] args) {
        String a = "AGGTAB";
        String b = "GXTXAYB";
        String lcs = computeLCS(a, b);
        System.out.println("String A: " + a);
        System.out.println("String B: " + b);
        System.out.println("LCS: " + lcs + " (Length: " + lcs.length() + ")");
    }
}
